func (q *Queries) UpdateParametrosRecompensa(ctx context.Context, arg UpdateParametrosRecompensaParams) (ParametrosRecompensa, error) {
	row := q.db.QueryRow(ctx, updateParametrosRecompensa,
		arg.MontoCompraPorPunto,
		arg.ValorPuntoPesos,
		arg.UpdatedBy,
		arg.ID,
	)
	var i ParametrosRecompensa
	err := row.Scan(
		&i.ID,
		&i.MontoCompraPorPunto,
		&i.ValorPuntoPesos,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}
